def task_func(df):
    required = {'id', 'age', 'income'}
    if not required.issubset(df.columns):
        raise ValueError("DataFrame must contain 'id', 'age', and 'income' columns")

    result = df.sort_values('id', kind='mergesort').copy()
    result[['age', 'income']] = result[['age', 'income']].astype(float)

    for positions in result.groupby('id', sort=False, dropna=False).indices.values():
        for column in ('age', 'income'):
            column_index = result.columns.get_loc(column)
            values = result.iloc[positions, column_index].tolist()
            if any(math.isinf(value) for value in values):
                raise ValueError('Values must be finite or NaN')

            valid = [value for value in values if not math.isnan(value)]
            if not valid:
                continue

            mean = math.fsum(valid) / len(valid)
            variance = math.fsum((value - mean) ** 2 for value in valid) / len(valid)
            scale = math.sqrt(variance) if variance else 1.0
            standardized = [(value - mean) / scale for value in values]
            result.iloc[positions, column_index] = standardized

    return result

