def task_func(df, column_name: str, pattern: str):
    result = df.copy()
    if not pattern:
        return result

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        parts = re.split(r'(\s+)', value)
        positions = [
            i for i in range(0, len(parts), 2)
            if parts[i] and regex.match(parts[i])
        ]
        words = [parts[i] for i in positions]
        for i, word in zip(positions, reversed(words)):
            parts[i] = word
        return ''.join(parts)

    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

