import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if not pattern:
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matched_words(text):
        words = str(text).split()
        matched = [word for word in words if regex.search(word)]
        matched.reverse()
        result = []
        index = 0
        for word in words:
            if regex.search(word):
                result.append(matched[index])
                index += 1
            else:
                result.append(word)
        return " ".join(result)

    new_df = df.copy()
    new_df[column_name] = new_df[column_name].apply(reverse_matched_words)
    return new_df

