def task_func(matrix):
    rows = [list(map(float, row)) for row in matrix]
    width = len(rows[0]) if rows else 0
    if any(len(row) != width for row in rows):
        raise ValueError("matrix must be rectangular")

    normalized = [[0.0] * width for _ in rows]
    for j in range(width):
        column = [row[j] for row in rows]
        if all(value == column[0] for value in column) and math.isfinite(column[0]):
            continue
        mean = sum(column) / len(column)
        deviations = [value - mean for value in column]
        std = math.hypot(*deviations) / math.sqrt(len(column))
        for i, deviation in enumerate(deviations):
            normalized[i][j] = deviation / std if std != 0.0 else 0.0

    return sys.modules["pandas"].DataFrame(normalized)

