from scipy.spatial.distance import pdist, squareform


def task_func(array):
    if not isinstance(array, list):
        raise TypeError("Input must be a list.")
    if not all(isinstance(sublist, list) for sublist in array):
        raise TypeError("Input must be a list of lists.")
    if not all(
        isinstance(item, (int, float)) for sublist in array for item in sublist
    ):
        raise TypeError("All elements in the sublists must be int or float.")

    columns = [chr(65 + i) for i in range(len(array[0]))]
    df = pd.DataFrame(array, columns=columns)

    int64_min, int64_max = -(2 ** 63), 2 ** 63 - 1

    def is_plain_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    for i, col in enumerate(columns):
        if not all(len(row) > i for row in array):
            continue
        values = [row[i] for row in array]
        has_int = any(is_plain_int(v) for v in values)
        has_float = any(isinstance(v, float) for v in values)
        if not (has_int and has_float):
            continue
        valid = all(
            (is_plain_int(v) and int64_min <= v <= int64_max)
            or (isinstance(v, float) and math.isfinite(v))
            for v in values
        )
        if valid:
            df[col] = pd.Series(values, index=df.index, dtype=object)

    distances = pdist(df.to_numpy(dtype=float), metric="euclidean")
    distance_matrix = pd.DataFrame(
        squareform(distances), index=df.index, columns=df.index
    )

    return df, distance_matrix

