        raise TypeError("Input must be a list of lists.")
    for sublist in array:
        for item in sublist:
            if not isinstance(item, (int, float)):
                raise TypeError("All elements in the sublists must be int or float.")

    width = len(array[0])
    columns = [chr(65 + i) for i in range(width)]
    df = pd.DataFrame(array, columns=columns)

    int_min, int_max = -(2 ** 63), 2 ** 63 - 1
    if all(len(row) == width for row in array):
        for j, col in enumerate(columns):
            values = [row[j] for row in array]
            has_float = False
            has_int = False
            eligible = True
            for v in values:
                if isinstance(v, bool):
                    eligible = False
                    break
                if isinstance(v, float):
                    if not math.isfinite(v):
                        eligible = False
                        break
                    has_float = True
                elif isinstance(v, int):
                    if not (int_min <= v <= int_max):
                        eligible = False
                        break
                    has_int = True
                else:
                    eligible = False
                    break
            if eligible and has_float and has_int:
                df[col] = pd.Series([float(v) for v in values], index=df.index, dtype="float64")

    distances = pdist(df.values, metric="euclidean")
    distance_matrix = pd.DataFrame(
        squareform(distances), index=df.index, columns=df.index
    )
    return df, distance_matrix

