import math


def task_func(array):
    class Vector(list):
        def __init__(self, values, dtype=None):
            super().__init__(values)
            self.dtype = dtype

        def tolist(self):
            return list(self)

        @property
        def shape(self):
            return (len(self),)

        def all(self):
            return all(self)

        def __eq__(self, other):
            if isinstance(other, (list, tuple, Vector)):
                return Vector(a == b for a, b in zip(self, other))
            return Vector(value == other for value in self)

    class Matrix(list):
        def __init__(self, rows, width):
            super().__init__(Vector(row) for row in rows)
            self.shape = (len(self), width)

        def tolist(self):
            return [list(row) for row in self]

        def __getitem__(self, key):
            if isinstance(key, tuple):
                row, column = key
                return list.__getitem__(self, row)[column]
            return list.__getitem__(self, key)

    class Indexer:
        def __init__(self, frame):
            self.frame = frame

        def __getitem__(self, key):
            if isinstance(key, tuple):
                row, column = key
                if isinstance(row, slice):
                    rows = self.frame._rows[row]
                    if isinstance(column, slice):
                        return Matrix([r[column] for r in rows], len(self.frame.columns[column]))
                    return Vector((r[column] for r in rows), self.frame.dtypes[column])
                if isinstance(column, slice):
                    return Vector(self.frame._rows[row][column])
                return self.frame._rows[row][column]
            return Vector(self.frame._rows[key])

    class DataFrame:
        def __init__(self, rows, columns, dtypes):
            self._rows = rows
            self.columns = Vector(columns)
            self.index = Vector(range(len(rows)))
            self.dtypes = Vector(dtypes)
            self.shape = (len(rows), len(columns))
            self.iloc = Indexer(self)

        def __len__(self):
            return len(self._rows)

        def __iter__(self):
            return iter(self.columns)

        def __getitem__(self, column):
            position = self.columns.index(column)
            return Vector((row[position] for row in self._rows), self.dtypes[position])

        @property
        def values(self):
            return Matrix(self._rows, len(self.columns))

        @property
        def empty(self):
            return not self._rows or not self.columns

        def to_numpy(self):
            return self.values

        def to_dict(self, orient='dict'):
            if orient == 'records':
                return [dict(zip(self.columns, row)) for row in self._rows]
            if orient == 'list':
                return {column: self[column].tolist() for column in self.columns}
            if orient == 'dict':
                return {column: dict(enumerate(self[column])) for column in self.columns}
            raise ValueError('Unsupported orientation')

        def equals(self, other):
            return self.shape == other.shape and list(self.columns) == list(other.columns) and self.to_dict('list') == other.to_dict('list')

    if not isinstance(array, list) or any(
        not isinstance(row, list)
        or any(not isinstance(value, (int, float)) for value in row)
        for row in array
    ):
        raise TypeError('Expected a list of lists containing integers or floats')

    width = max((len(row) for row in array), default=0)
    rows = [row[:] + [math.nan] * (width - len(row)) for row in array]
    dtypes = []
    for column in range(width):
        values = [row[column] for row in rows]
        integers = [value for value in values if isinstance(value, int)]
        floats = [value for value in values if isinstance(value, float)]
        if floats and all(-(2 ** 63) <= value < 2 ** 63 for value in integers):
            dtype = 'float64'
            for row in rows:
                row[column] = float(row[column])
        elif not floats and all(-(2 ** 63) <= value < 2 ** 63 for value in integers):
            dtype = 'bool' if all(isinstance(value, bool) for value in integers) else 'int64'
        elif not floats and all(0 <= value < 2 ** 64 for value in integers):
            dtype = 'uint64'
        else:
            dtype = 'object'
        dtypes.append(dtype)

    count = len(rows)
    distances = [[0.0] * count for _ in range(count)]
    for i in range(count):
        for j in range(i + 1, count):
            total = 0.0
            for a, b in zip(rows[i], rows[j]):
                difference = float(a) - float(b)
                total += difference * difference
            distances[i][j] = distances[j][i] = math.sqrt(total)

    return (
        DataFrame(rows, [chr(65 + i) for i in range(width)], dtypes),
        DataFrame(distances, list(range(count)), ['float64'] * count),
    )

