import math


def task_func(df, target):
    y = [float(value) for value in df[target].tolist()]
    rows = df.drop(columns=[target]).to_numpy().tolist()
    n = len(y)
    if n == 0:
        raise ValueError('At least one sample is required.')
    p = len(rows[0])
    if p == 0:
        raise ValueError('At least one feature is required.')
    rows = [[float(value) for value in row] for row in rows]
    if any(not math.isfinite(value) for value in y):
        raise ValueError('Target values must be finite.')
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError('Feature values must be finite.')
    if n < 2 or all(value == y[0] for value in y):
        return float('nan')

    mean_y = math.fsum(y) / n
    residual = [value - mean_y for value in y]
    total = math.fsum(value * value for value in residual)
    columns = []
    for j in range(p):
        mean = math.fsum(row[j] for row in rows) / n
        columns.append([row[j] - mean for row in rows])

    largest_norm = max(math.hypot(*column) for column in columns)
    tolerance = math.ulp(1.0) * max(n, p) * largest_norm
    for _ in range(min(n - 1, p)):
        pivot = max(range(len(columns)), key=lambda j: math.hypot(*columns[j]))
        column = columns.pop(pivot)
        norm = math.hypot(*column)
        if norm <= tolerance:
            break
        basis = [value / norm for value in column]
        for _ in range(2):
            projection = math.fsum(a * b for a, b in zip(basis, residual))
            residual = [value - projection * b for value, b in zip(residual, basis)]
        for column in columns:
            for _ in range(2):
                projection = math.fsum(a * b for a, b in zip(basis, column))
                for i in range(n):
                    column[i] -= projection * basis[i]
        if not columns:
