def task_func(df, target):
    import math
    import sys

    y = [float(value) for value in df[target]]
    rows = [tuple(map(float, row)) for row in df.drop(columns=[target]).itertuples(index=False, name=None)]
    n = len(y)
    if n == 0:
        raise ValueError("At least one sample is required.")
    if not rows[0]:
        raise ValueError("At least one feature is required.")
    if any(not math.isfinite(value) for value in y):
        raise ValueError("The target must contain only finite numbers.")
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError("Features must contain only finite numbers.")
    if all(value == y[0] for value in y):
        return 1.0

    mean_y = math.fsum(y) / n
    centered_y = [value - mean_y for value in y]
    columns = []
    for values in zip(*rows):
        mean = math.fsum(values) / n
        columns.append([value - mean for value in values])

    norms = [math.hypot(*column) for column in columns]
    tolerance = sys.float_info.epsilon * max(n, len(columns)) * max(norms)
    fitted = [0.0] * n

    while columns:
        pivot = max(range(len(columns)), key=lambda index: norms[index])
        norm = norms.pop(pivot)
        column = columns.pop(pivot)
        if norm <= tolerance:
            break
        direction = [value / norm for value in column]
        coefficient = math.fsum(a * b for a, b in zip(direction, centered_y))
        for i in range(n):
            fitted[i] += coefficient * direction[i]
        for j, remaining in enumerate(columns):
            for _ in range(2):
                projection = math.fsum(a * b for a, b in zip(direction, remaining))
                for i in range(n):
                    remaining[i] -= projection * direction[i]
            norms[j] = math.hypot(*remaining)

    residual_sum = math.fsum((actual - predicted) ** 2 for actual, predicted in zip(centered_y, fitted))
    total_sum = math.fsum(value ** 2 for value in centered_y)
    return float(1.0 - residual_sum / total_sum)

