            if isinstance(key, list):
                positions = [self.columns.index(column) for column in key]
                return DataFrame([[row[i] for i in positions] for row in self._rows], key)
            position = self.columns.index(key)
            return Series(row[position] for row in self._rows)

        @property
        def shape(self):
            return len(self._rows), len(self.columns)

        @property
        def empty(self):
            return not self._rows or not self.columns

        @property
        def values(self):
            return Series(Series(row) for row in self._rows)

        def to_dict(self, orient='dict'):
            if orient == 'records':
                return [dict(zip(self.columns, row)) for row in self._rows]
            if orient == 'list':
                return {column: self[column].tolist() for column in self.columns}
            if orient == 'dict':
                return {column: dict(enumerate(self[column])) for column in self.columns}
            raise ValueError('Unsupported orientation')

        def equals(self, other):
            return list(self.columns) == list(other.columns) and self.to_dict('list') == other.to_dict('list')

    rows = [list(row) for row in data]
    columns = list(cols)
    if not rows or not columns:
        raise ValueError('At least one sample and one feature are required')
    if any(len(row) != len(columns) for row in rows):
        raise ValueError('Each row must match the number of columns')

    points = [tuple(float(value) for value in row) for row in rows]
    if any(not isfinite(value) for point in points for value in point):
        raise ValueError('All feature values must be finite')

    neighbors = [[] for _ in points]
    for i, point in enumerate(points):
        neighbors[i].append(i)
        for j in range(i):
            distance_squared = sum((a - b) * (a - b) for a, b in zip(point, points[j]))
            if distance_squared <= 9.0:
                neighbors[i].append(j)
                neighbors[j].append(i)

    labels = [-2] * len(points)
    cluster = 0
    for seed in range(len(points)):
        if labels[seed] != -2:
            continue
        if len(neighbors[seed]) < 2:
            labels[seed] = -1
            continue
        labels[seed] = cluster
        pending = deque(neighbors[seed])
        while pending:
            index = pending.popleft()
            if labels[index] == -1:
                labels[index] = cluster
            elif labels[index] == -2:
                labels[index] = cluster
                if len(neighbors[index]) >= 2:
                    pending.extend(neighbors[index])
        cluster += 1

    if len(columns) == 1:
        minima = {}
        for point, label in zip(points, labels):
            if label >= 0:
                minima[label] = min(minima.get(label, point[0]), point[0])
        mapping = {label: rank for rank, label in enumerate(sorted(minima, key=minima.get))}
        labels = [mapping[label] if label >= 0 else -1 for label in labels]

    if 'Cluster' in columns:
        position = columns.index('Cluster')
        for row, label in zip(rows, labels):
            row[position] = label
    else:
        columns.append('Cluster')
        for row, label in zip(rows, labels):
            row.append(label)
    return DataFrame(rows, columns)

