    for i in range(n):
        if labels[i] != -1 or not is_core[i]:
            continue
        labels[i] = current
        stack = [i]
        while stack:
            p = stack.pop()
            if not is_core[p]:
                continue
            for q in neighbors[p]:
                if labels[q] == -1:
                    labels[q] = current
                    if is_core[q]:
                        stack.append(q)
        current += 1

    if len(cols) == 1 and current > 1:
        mapping = {}
        for label in labels:
            if label != -1 and label not in mapping:
                mapping[label] = len(mapping)
        labels = [mapping[label] if label != -1 else -1 for label in labels]

    df['Cluster'] = pd.Series(labels, index=df.index, dtype='int64')
