                    + value.rjust(value_width)
                )
            return '\n'.join(lines)

    pairs = list(list_of_pairs)
    if not pairs:
        raise ValueError('Input must not be empty')

    categories = []
    values = []
    for category, value in pairs:
        try:
            number = float(value)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError('Values must be numeric') from exc
        if math.isinf(number):
            raise ValueError('Values must not contain infinity')
        categories.append(category)
        values.append(number)

    observed = [value for value in values if not math.isnan(value)]
    if observed:
        minimum = min(observed)
        span = max(observed) - minimum
        if span < 10 * math.ulp(1.0):
            span = 1.0
        scale = 1.0 / span
        offset = -minimum * scale
        normalized = [value * scale + offset for value in values]
    else:
        normalized = values

    return DataFrame(categories, normalized)

