import math


def task_func(data, target, k):
    if not isinstance(k, int) or isinstance(k, bool) or k < 0:
        raise ValueError("'k' must be a non-negative integer")

    radius_earth_km = 6371.0

    def haversine(lat1, lon1, lat2, lon2):
        lat1, lon1, lat2, lon2 = map(math.radians, (lat1, lon1, lat2, lon2))
        dlat = lat2 - lat1
        dlon = lon2 - lon1
        a = math.sin(dlat / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin(dlon / 2) ** 2
        a = min(1.0, max(0.0, a))
        return radius_earth_km * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))

    points = data[['Latitude', 'Longitude']].values.tolist()
    target_lat, target_lon = target[0], target[1]

    scored = [(haversine(target_lat, target_lon, p[0], p[1]), p) for p in points]
    scored.sort(key=lambda item: item[0])

    groups = []
    for dist, point in scored:
        if groups and math.isclose(dist, groups[-1][0], rel_tol=1e-9, abs_tol=1e-9):
            groups[-1][1].append(point)
        else:
            groups.append((dist, [point]))

    ordered = []
    for _, members in groups:
        distinct = {tuple(p) for p in members}
        if len(distinct) == 2:
            members = sorted(members, key=lambda p: (p[0], p[1]))
        ordered.extend(members)

    return ordered[:k]

