)


def _is_pictographic(cp):
    for low, high in _PICTOGRAPHIC_RANGES:
        if low <= cp <= high:
            return True
    return False


def _break_property(ch):
    cp = ord(ch)
    if cp == 0x0D:
        return 'CR'
    if cp == 0x0A:
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if (cp == 0x200C or 0xFE00 <= cp <= 0xFE0F or 0x1F3FB <= cp <= 0x1F3FF
            or 0xE0020 <= cp <= 0xE007F or 0xE0100 <= cp <= 0xE01EF):
        return 'Extend'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    if (0x0600 <= cp <= 0x0605 or cp in (0x06DD, 0x070F, 0x0890, 0x0891, 0x08E2, 0x110BD, 0x110CD)):
        return 'Prepend'
    category = unicodedata.category(ch)
    if category in ('Mn', 'Me'):
        return 'Extend'
    if category == 'Mc':
        return 'SpacingMark'
    if category in ('Cc', 'Cf', 'Zl', 'Zp', 'Cs'):
        return 'Control'
    if _is_pictographic(cp):
        return 'ExtPict'
    return 'Other'


def _grapheme_count(text):
    count = 0
    prev = None
    ri_run = 0
    emoji_state = 0
    for ch in text:
        prop = _break_property(ch)
        if prev is None:
            boundary = True
        elif prev == 'CR' and prop == 'LF':
            boundary = False
        elif prev in ('CR', 'LF', 'Control') or prop in ('CR', 'LF', 'Control'):
            boundary = True
        elif prev == 'L' and prop in ('L', 'V', 'LV', 'LVT'):
            boundary = False
        elif prev in ('LV', 'V') and prop in ('V', 'T'):
            boundary = False
        elif prev in ('LVT', 'T') and prop == 'T':
            boundary = False
        elif prop in ('Extend', 'ZWJ', 'SpacingMark'):
            boundary = False
        elif prev == 'Prepend':
            boundary = False
        elif prev == 'ZWJ' and prop == 'ExtPict' and emoji_state == 2:
            boundary = False
        elif prev == 'RI' and prop == 'RI' and ri_run % 2 == 1:
            boundary = False
        else:
            boundary = True

        if boundary:
            count += 1

        if prop == 'ExtPict':
            emoji_state = 1
        elif prop == 'Extend' and emoji_state == 1:
            emoji_state = 1
        elif prop == 'ZWJ' and emoji_state == 1:
            emoji_state = 2
        else:
            emoji_state = 0

        ri_run = ri_run + 1 if prop == 'RI' else 0
        prev = prop
    return count


