        return float("nan")

    mean = sum(values) / n
    m2 = sum((v - mean) ** 2 for v in values) / n
    m3 = sum((v - mean) ** 3 for v in values) / n

    if not math.isfinite(m2) or not math.isfinite(m3) or m2 == 0:
