import re
import math
from collections import Counter


def task_func(example_str):
    def replace(match):
        start, end = match.start(), match.end()
        before = example_str[start - 1] if start > 0 else ''
        after = example_str[end] if end < len(example_str) else ''
        if before.isalpha() and after.isalpha():
            return ' '
        return ''

    text = re.sub(r'\[.*?\]', replace, example_str)
    if not text.strip():
        return {}

    tokens = re.findall(r'(?u)\b\w\w+\b', text.lower())
    if not tokens:
        raise ValueError('empty vocabulary; perhaps the documents only contain stop words')

    counts = Counter(tokens)
    idf = math.log(2.0 / 2.0) + 1.0
    weights = {word: count * idf for word, count in counts.items()}
    norm = math.sqrt(sum(value * value for value in weights.values()))
    return {word: weights[word] / norm for word in sorted(weights)}

