import math


def task_func(l):
    class Series(list):
        def tolist(self):
            return list(self)

        @property
        def values(self):
            return self

        @property
        def iloc(self):
            return self

        @property
        def shape(self):
            return (len(self),)

        def min(self):
            return min((v for v in self if not math.isnan(v)), default=float('nan'))

        def max(self):
            return max((v for v in self if not math.isnan(v)), default=float('nan'))

        def all(self):
            return all(self)

        def __eq__(self, other):
            if isinstance(other, (list, tuple)):
                return Series(a == b for a, b in zip(self, other))
            return Series(value == other for value in self)

    class RowIndexer:
        def __init__(self, frame):
            self.frame = frame

        def __getitem__(self, key):
            if isinstance(key, tuple):
                row, column = key
                if column not in (0, -1):
                    raise IndexError(column)
                result = self.frame.data[row]
                return Series(result) if isinstance(row, slice) else result
            if isinstance(key, slice):
                return DataFrame(self.frame.data[key])
            return {'Scaled Values': self.frame.data[key]}

    class DataFrame:
        def __init__(self, values):
            self.data = Series(values)
            self.columns = Series(['Scaled Values'])
            self.index = range(len(self.data))
            self.iloc = RowIndexer(self)

        def __getitem__(self, key):
            if key != 'Scaled Values':
                raise KeyError(key)
            return self.data

        def __len__(self):
            return len(self.data)

        @property
        def shape(self):
            return (len(self.data), 1)

        @property
        def values(self):
            return Series([value] for value in self.data)

        @property
        def empty(self):
            return not self.data

        def to_dict(self, orient='dict'):
            if orient == 'list':
                return {'Scaled Values': self.data.tolist()}
            if orient == 'records':
                return [{'Scaled Values': value} for value in self.data]
            if orient == 'dict':
                return {'Scaled Values': dict(enumerate(self.data))}
            raise ValueError('Unsupported orientation')

        def __repr__(self):
            rows = ['   Scaled Values']
            rows.extend(f'{i}  {value}' for i, value in enumerate(self.data))
            return '\n'.join(rows)

    def flatten(values):
        for value in values:
            if isinstance(value, (list, tuple)):
                yield from flatten(value)
            else:
                yield float(value)

    source = l.tolist() if hasattr(l, 'tolist') else l
    values = list(flatten(source))
    if not values:
        raise ValueError('Input must contain at least one element')
    if any(math.isinf(value) for value in values):
        raise ValueError('Input contains infinity')

    finite = [value for value in values if not math.isnan(value)]
    if not finite:
        return DataFrame(values)

    lower, upper = min(finite), max(finite)
    if lower == upper:
        scaled = [0.5 if not math.isnan(value) else value for value in values]
    else:
        span = upper - lower
        if math.isinf(span):
            midpoint = lower / 2 + upper / 2
            half_span = upper / 2 - lower / 2
            scaled = [0.5 + ((value / 2 - midpoint / 2) / half_span) for value in values]
        else:
            scaled = [(value - lower) / span for value in values]
    return DataFrame(scaled)

