import pandas as pd


def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    def keep_first(pairs):
        result = {}
        for key, value in pairs:
            if key not in result:
                result[key] = value
        return result

    numbers = re.compile(r"^-?\d+(?:\.\d+)?$")

    my_dict = json.loads(json_str, object_pairs_hook=keep_first)
