        return pd.DataFrame()

    data = json.loads(json_str, object_pairs_hook=dict)
    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = re.compile(r'[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?')

    def normalize(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value) * 2
        if isinstance(value, list):
            return [normalize(item) for item in value]
        if isinstance(value, str):
            numbers = number_pattern.findall(value)
            if not numbers:
                return value
            doubled = [float(number) * 2 for number in numbers]
            return doubled[0] if len(doubled) == 1 else doubled
        return value

    normalized = {key: normalize(value) for key, value in data.items()}
    try:
        if all(not isinstance(value, (list, dict)) for value in normalized.values()):
            return pd.DataFrame([normalized])
        return pd.DataFrame(normalized)
    except (TypeError, ValueError):
        return pd.DataFrame()

