def task_func(P, T):
    import math
    import sys

    if P.ndim != 2 or T.ndim != 3:
        raise ValueError('P must be a matrix and T must be a 3D tensor')
    if P.size == 0 or T.size == 0:
        raise ValueError('Inputs must not be empty')
    if P.shape[1] != T.shape[0]:
        raise ValueError('Input shapes are incompatible')

    wrap = P.dtype == T.dtype and P.dtype.kind in ('i', 'u')
    if wrap:
        bits = P.dtype.itemsize * 8
        modulus = 1 << bits
        signed = P.dtype.kind == 'i'
        midpoint = modulus >> 1

    matrix = P.tolist()
    tensor = T.tolist()
    rows = len(matrix)
    columns = T.shape[1] * T.shape[2]
    values = []

    for row in matrix:
        result = []
        for j in range(T.shape[1]):
            for k in range(T.shape[2]):
                total = sum(row[h] * tensor[h][j][k] for h in range(len(row)))
                if wrap:
                    total %= modulus
                    if signed and total >= midpoint:
                        total -= modulus
                value = float(total)
                if math.isinf(value):
                    raise ValueError('The product contains infinity')
                result.append(value)
        values.append(result)

    epsilon = sys.float_info.epsilon
    for column in range(columns):
        observed = [row[column] for row in values if not math.isnan(row[column])]
        if not observed:
            continue
        count = len(observed)
        mean = math.fsum(value / count for value in observed)
        variance = math.fsum((value - mean) ** 2 / count for value in observed)
        constant_bound = count * epsilon * variance + (count * mean * epsilon) ** 2
        scale = 1.0 if variance <= constant_bound else math.sqrt(variance)
        for row in values:
            row[column] = (row[column] - mean) / scale

    dataframe = sys.modules.get('pandas')
    if dataframe is None:
        raise RuntimeError('pandas must be loaded to construct the requested DataFrame')
    return dataframe.DataFrame(values, columns=[f'feature_{i}' for i in range(columns)])

