def task_func(matrix1, matrix2):
    def kind(m):
        dtype = getattr(m, "dtype", None)
        if dtype is not None:
            return dtype.kind
        values = [v for row in m for v in row]
        if values and all(isinstance(v, float) for v in values):
            return "f"
        return "o"

    both_float = kind(matrix1) == "f" and kind(matrix2) == "f"

    def fmt(value):
        if both_float:
            text = str(value)
            if text.startswith("np."):
                text = repr(float(value))
            return text
        if hasattr(value, "item"):
            value = value.item()
        return str(value)

    rows1 = [list(row) for row in matrix1]
    rows2 = [list(row) for row in matrix2]
    if len(rows1) != len(rows2):
        raise ValueError("Matrices must have the same number of rows")

    table = [[fmt(v) for v in r1 + r2] for r1, r2 in zip(rows1, rows2)]
    if not table:
        return ""

    n_cols = max(len(row) for row in table)
    widths = [0] * n_cols
    for row in table:
        for j, cell in enumerate(row):
            widths[j] = max(widths[j], len(cell))

    lines = []
    for row in table:
        cells = [cell.rjust(widths[j]) for j, cell in enumerate(row)]
        lines.append(" " + " ".join(cells))
    return "\n".join(lines)

def task_func(matrix1, matrix2):
    shape1 = matrix1.shape
    shape2 = matrix2.shape
    if len(shape1) != 2 or len(shape2) != 2:
        raise ValueError('Both matrices must be two-dimensional')
    if shape1[0] != shape2[0]:
        raise ValueError('Both matrices must have the same number of rows')

    row_count = shape1[0]
    column_count = shape1[1] + shape2[1]
    if row_count == 0 or column_count == 0:
        columns = ', '.join(map(str, range(column_count)))
        indices = ', '.join(map(str, range(row_count)))
        return f'Empty DataFrame\nColumns: [{columns}]\nIndex: [{indices}]'

    both_floating = matrix1.dtype.kind == matrix2.dtype.kind == 'f'
    promote_to_float = not both_floating and 'f' in (
        matrix1.dtype.kind, matrix2.dtype.kind
    )

    rows = []
    for left, right in zip(matrix1, matrix2):
        fields = []
        for value in (*left, *right):
            if promote_to_float:
                value = float(value)
            field = str(value)
            fields.append('NaN' if field == 'nan' else field)
        rows.append(fields)

    widths = [max(len(row[column]) for row in rows)
              for column in range(column_count)]
    return '\n'.join(
        ' '.join(field.rjust(width) for field, width in zip(row, widths))
        for row in rows
    )

