    else:
        mean_feature = fsum(features) / len(features)
        centered_features = [x - mean_feature for x in features]
        numerator = fsum(
            x * (y - mean_value)
            for x, y in zip(centered_features, values)
        )
        denominator = fsum(x * x for x in centered_features)
        coefficient = numerator / denominator
        intercept = mean_value - coefficient * mean_feature

    return {'coefficients': [[coefficient]], 'intercept': [intercept]}

