import math


def task_func(df):
    n, p = df.shape
    if min(n, p) < 2:
        raise ValueError('PCA with two components requires at least two rows and two columns.')

    data = [[float(value) for value in row] for row in df.itertuples(index=False, name=None)]
    if any(not math.isfinite(value) for row in data for value in row):
        raise ValueError('Input must contain only finite numeric values.')

    means = [math.fsum(row[j] for row in data) / n for j in range(p)]
    centered = [[row[j] - means[j] for j in range(p)] for row in data]
    matrix = [[0.0] * p for _ in range(p)]
    for i in range(p):
        for j in range(i, p):
            value = math.fsum(row[i] * row[j] for row in centered)
            matrix[i][j] = matrix[j][i] = value

    vectors = [[float(i == j) for j in range(p)] for i in range(p)]
    tolerance = max(matrix[i][i] for i in range(p)) * 1e-15

    for _ in range(100):
        changed = False
        for i in range(p - 1):
            for j in range(i + 1, p):
                off = matrix[i][j]
                if abs(off) <= tolerance:
                    continue
                changed = True
                tau = (matrix[j][j] - matrix[i][i]) / (2.0 * off)
                tangent = math.copysign(1.0, tau) / (abs(tau) + math.hypot(1.0, tau))
                cosine = 1.0 / math.hypot(1.0, tangent)
                sine = tangent * cosine
                matrix[i][i] -= tangent * off
                matrix[j][j] += tangent * off
                matrix[i][j] = matrix[j][i] = 0.0

                for k in range(p):
                    if k != i and k != j:
                        a, b = matrix[k][i], matrix[k][j]
                        matrix[k][i] = matrix[i][k] = cosine * a - sine * b
                        matrix[k][j] = matrix[j][k] = sine * a + cosine * b
                    a, b = vectors[k][i], vectors[k][j]
                    vectors[k][i] = cosine * a - sine * b
                    vectors[k][j] = sine * a + cosine * b
        if not changed:
            break

    components = sorted(range(p), key=lambda j: matrix[j][j], reverse=True)[:2]
    result = {}
    for number, component in enumerate(components, start=1):
        scores = [math.fsum(row[j] * vectors[j][component] for j in range(p)) for row in centered]
        pivot = max(range(n), key=lambda i: abs(scores[i]))
        if scores[pivot] < 0:
            scores = [-value for value in scores]
        result[f'PC{number}'] = scores

    return df.__class__(result, index=df.index)

