def task_func(df, column, alpha):
    import math
    from statistics import NormalDist

    def polynomial(coefficients, x):
        result = 0.0
        for coefficient in reversed(coefficients):
            result = result * x + coefficient
        return result

    values = sorted(float(value) for value in df[column].dropna())
    n = len(values)
    if n < 3 or any(not math.isfinite(value) for value in values):
        return False
    if values[0] == values[-1]:
        return bool(1.0 > alpha)

    scale = max(abs(values[0]), abs(values[-1]))
    values = [value / scale for value in values]
    span = values[-1] - values[0]
    minimum = values[0]
    values = [(value - minimum) / span for value in values]

    half = n // 2
    if n == 3:
        weights = [math.sqrt(0.5)]
    else:
        normal = NormalDist()
        weights = [normal.inv_cdf((i + 0.625) / (n + 0.25))
                   for i in range(half)]
        squared_sum = 2.0 * math.fsum(weight * weight for weight in weights)
        root_sum = math.sqrt(squared_sum)
        inverse_root_n = 1.0 / math.sqrt(n)
        first = polynomial(
            (0.0, 0.221157, -0.147981, -2.07119, 4.434685, -2.706056),
            inverse_root_n,
        ) - weights[0] / root_sum
        if n > 5:
            second = polynomial(
                (0.0, 0.042981, -0.293762, -1.752461, 5.682633, -3.582633),
                inverse_root_n,
            ) - weights[1] / root_sum
            factor = math.sqrt(
                (squared_sum - 2.0 * weights[0] ** 2 - 2.0 * weights[1] ** 2)
                / (1.0 - 2.0 * first ** 2 - 2.0 * second ** 2)
            )
            weights[1] = second
            start = 2
        else:
            factor = math.sqrt(
                (squared_sum - 2.0 * weights[0] ** 2)
                / (1.0 - 2.0 * first ** 2)
            )
            start = 1
        weights[0] = first
        for i in range(start, half):
            weights[i] /= -factor

    mean = math.fsum(values) / n
    denominator = math.fsum((value - mean) ** 2 for value in values)
    numerator = math.fsum(
        weights[i] * (values[n - 1 - i] - values[i])
        for i in range(half)
    )
    w = min(1.0, max(0.0, numerator * numerator / denominator))

    if n == 3:
        p_value = max(0.0, 1.0 - 6.0 / math.pi * math.acos(math.sqrt(w)))
    elif w == 1.0:
        p_value = 1.0
    else:
        y = math.log1p(-w)
        if n <= 11:
            gamma = -2.273 + 0.459 * n
            if y >= gamma:
                return bool(1e-19 > alpha)
            y = -math.log(gamma - y)
            location = polynomial((0.5440, -0.39978, 0.025054, -0.0006714), n)
            spread = math.exp(polynomial((1.3822, -0.77857, 0.062767, -0.0020322), n))
        else:
            log_n = math.log(n)
            location = polynomial((-1.5861, -0.31082, -0.083751, 0.0038915), log_n)
            spread = math.exp(polynomial((-0.4803, -0.082676, 0.0030302), log_n))
        p_value = 0.5 * math.erfc((y - location) / (spread * math.sqrt(2.0)))
    return bool(p_value > alpha)

