            factor = math.sqrt(
                (squared_sum - 2 * weights[0] ** 2 - 2 * weights[1] ** 2)
                / (1 - 2 * first ** 2 - 2 * second ** 2)
            )
            weights[1] = second
            start = 2
        else:
            factor = math.sqrt(
                (squared_sum - 2 * weights[0] ** 2) / (1 - 2 * first ** 2)
            )
