import math
import operator


def task_func(tuples_list, n_components):
    class PCAResult(list):
        @property
        def shape(self):
            return (len(self), len(self[0]) if self else 0)

        def tolist(self):
            return [list(row) for row in self]

        def __getitem__(self, key):
            if not isinstance(key, tuple):
                return super().__getitem__(key)
            rows, columns = key
            selected = super().__getitem__(rows)
            if isinstance(rows, slice):
                values = [row[columns] for row in selected]
                return PCAResult(values) if isinstance(columns, slice) else values
            return selected[columns]

    data = [list(map(float, row)) for row in tuples_list]
    if not data or not data[0]:
        raise ValueError('Expected a nonempty two-dimensional dataset')

    n_samples = len(data)
    n_features = len(data[0])
    if any(len(row) != n_features for row in data):
        raise ValueError('All observations must have the same number of features')
    if any(not math.isfinite(value) for row in data for value in row):
        raise ValueError('All values must be finite')

    limit = min(n_samples, n_features)
    if n_components is None:
        n_components = limit
    else:
        n_components = operator.index(n_components)
    if not 0 <= n_components <= limit:
        raise ValueError('n_components must be between zero and min(n_samples, n_features)')

    means = [
        math.fsum(row[j] for row in data) / n_samples
        for j in range(n_features)
    ]
    columns = [
        [row[j] - means[j] for row in data]
        for j in range(n_features)
    ]

    for _ in range(100):
        changed = False
        for p in range(n_features - 1):
            for q in range(p + 1, n_features):
                left, right = columns[p], columns[q]
                alpha = math.fsum(value * value for value in left)
                beta = math.fsum(value * value for value in right)
                gamma = math.fsum(a * b for a, b in zip(left, right))
                if alpha == 0.0 or beta == 0.0:
                    continue
                if abs(gamma) <= 1e-14 * math.sqrt(alpha) * math.sqrt(beta):
                    continue

                tau = (beta - alpha) / (2.0 * gamma)
                tangent = math.copysign(1.0, tau) / (abs(tau) + math.hypot(1.0, tau))
                cosine = 1.0 / math.sqrt(1.0 + tangent * tangent)
                sine = cosine * tangent
                columns[p] = [cosine * a - sine * b for a, b in zip(left, right)]
                columns[q] = [sine * a + cosine * b for a, b in zip(left, right)]
                changed = True
        if not changed:
            break

    columns.sort(
        key=lambda column: math.fsum(value * value for value in column),
        reverse=True,
    )
    selected = columns[:n_components]
    for j, column in enumerate(selected):
        if column[0] < 0.0:
            selected[j] = [-value for value in column]

    return PCAResult([
        [column[i] for column in selected]
        for i in range(n_samples)
    ])

def task_func(tuples_list, n_components):
    import math
    import operator

    rows = [list(map(float, row)) for row in tuples_list]
    if not rows or not rows[0]:
        raise ValueError("Input must contain at least one observation and feature")
    n_samples = len(rows)
    n_features = len(rows[0])
    if any(len(row) != n_features for row in rows):
        raise ValueError("All observations must have the same number of features")
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError("Input values must be finite")

    limit = min(n_samples, n_features)
    if n_components is None:
        count = limit
    else:
        try:
            count = operator.index(n_components)
        except TypeError:
            raise ValueError("n_components must be an integer") from None
        if not 0 <= count <= limit:
            raise ValueError("n_components is outside the valid range")

    means = [math.fsum(row[j] for row in rows) / n_samples
             for j in range(n_features)]
    centered = [[value - means[j] for j, value in enumerate(row)]
                for row in rows]
    covariance = [[0.0] * n_features for _ in range(n_features)]
    for i in range(n_features):
        for j in range(i, n_features):
            value = math.fsum(row[i] * row[j] for row in centered)
            covariance[i][j] = covariance[j][i] = value

    vectors = [[float(i == j) for j in range(n_features)]
               for i in range(n_features)]
    scale = max(abs(value) for row in covariance for value in row)
    tolerance = scale * 2.220446049250313e-16

    for _ in range(100):
        largest = 0.0
        for p in range(n_features):
            for q in range(p + 1, n_features):
                off_diagonal = covariance[p][q]
                largest = max(largest, abs(off_diagonal))
                if abs(off_diagonal) <= tolerance:
                    continue
                tau = (covariance[q][q] - covariance[p][p]) / (2.0 * off_diagonal)
                tangent = math.copysign(1.0, tau) / (abs(tau) + math.hypot(1.0, tau))
                cosine = 1.0 / math.hypot(1.0, tangent)
                sine = tangent * cosine
                covariance[p][p] -= tangent * off_diagonal
                covariance[q][q] += tangent * off_diagonal
                covariance[p][q] = covariance[q][p] = 0.0
                for k in range(n_features):
                    if k != p and k != q:
                        left, right = covariance[k][p], covariance[k][q]
                        covariance[k][p] = covariance[p][k] = cosine * left - sine * right
                        covariance[k][q] = covariance[q][k] = sine * left + cosine * right
                    left, right = vectors[k][p], vectors[k][q]
                    vectors[k][p] = cosine * left - sine * right
                    vectors[k][q] = sine * left + cosine * right
        if largest <= tolerance:
            break

    order = sorted(range(n_features), key=lambda j: covariance[j][j], reverse=True)
    transformed = [[] for _ in rows]
    for component in order[:count]:
        scores = [math.fsum(row[j] * vectors[j][component]
                            for j in range(n_features))
                  for row in centered]
        largest = max(abs(score) for score in scores)
        pivot = next((i for i, score in enumerate(scores)
                      if math.isclose(abs(score), largest, rel_tol=1e-14, abs_tol=0.0)), 0)
        direction = -1.0 if scores[pivot] < 0.0 else 1.0
        for result, score in zip(transformed, scores):
            result.append(direction * score)
    return transformed

