            if any(h in word for h in '-‐‑') else len(word)
            for word in words
        ]

    def beta_fraction(a, b, x):
        tiny = 1e-300
        c = 1.0
        d = 1.0 - (a + b) * x / (a + 1.0)
        if abs(d) < tiny:
            d = tiny
        d = 1.0 / d
        result = d
        for m in range(1, 501):
            coefficients = (
                m * (b - m) * x / ((a + 2*m - 1) * (a + 2*m)),
                -(a + m) * (a + b + m) * x
                / ((a + 2*m) * (a + 2*m + 1)),
            )
            for coefficient in coefficients:
                d = 1.0 + coefficient * d
                c = 1.0 + coefficient / c
                if abs(d) < tiny:
                    d = tiny
                if abs(c) < tiny:
                    c = tiny
                d = 1.0 / d
                delta = d * c
                result *= delta
            if abs(delta - 1.0) < 1e-15:
