        factor = math.exp(
            math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
            + a * math.log(x) + b * math.log1p(-x)
        )
        if x < (a + 1.0) / (a + b + 2.0):
            return factor * beta_fraction(a, b, x) / a
        return 1.0 - factor * beta_fraction(b, a, 1.0 - x) / b

    lengths1 = word_lengths(text1)
    lengths2 = word_lengths(text2)
    n = len(lengths1)
    if n != len(lengths2) or n < 2:
        return float('nan'), float('nan')

    differences = [a - b for a, b in zip(lengths1, lengths2)]
    mean = math.fsum(differences) / n
    squared_deviations = math.fsum((d - mean) ** 2 for d in differences)
    if squared_deviations == 0.0:
        if mean == 0.0:
            return float('nan'), float('nan')
        return math.copysign(float('inf'), mean), 0.0

    t_statistic = mean / math.sqrt(squared_deviations / (n * (n - 1)))
    degrees_of_freedom = n - 1
    x = degrees_of_freedom / (degrees_of_freedom + t_statistic ** 2)
    p_value = regularized_beta(x, degrees_of_freedom / 2.0, 0.5)
    return float(t_statistic), min(1.0, max(0.0, p_value))

import math
import re


def _betacf(a, b, x):
    max_iter = 300
    eps = 3e-16
    fpmin = 1e-300
    qab = a + b
    qap = a + 1.0
    qam = a - 1.0
    c = 1.0
    d = 1.0 - qab * x / qap
    if abs(d) < fpmin:
        d = fpmin
    d = 1.0 / d
    h = d
    for m in range(1, max_iter + 1):
        m2 = 2 * m
        aa = m * (b - m) * x / ((qam + m2) * (a + m2))
        d = 1.0 + aa * d
        if abs(d) < fpmin:
            d = fpmin
        c = 1.0 + aa / c
        if abs(c) < fpmin:
            c = fpmin
        d = 1.0 / d
        h *= d * c
        aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
        d = 1.0 + aa * d
        if abs(d) < fpmin:
            d = fpmin
        c = 1.0 + aa / c
        if abs(c) < fpmin:
            c = fpmin
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < eps:
            break
    return h


def _betainc(a, b, x):
    if x <= 0.0:
        return 0.0
    if x >= 1.0:
        return 1.0
    log_bt = (math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
              + a * math.log(x) + b * math.log1p(-x))
    bt = math.exp(log_bt)
    if x < (a + 1.0) / (a + b + 2.0):
        return bt * _betacf(a, b, x) / a
    return 1.0 - bt * _betacf(b, a, 1.0 - x) / b


def _word_lengths(text):
    words = re.findall(r"\w+(?:-\w+)+|\w+", text)
    lengths = []
    for word in words:
        if '-' in word:
            lengths.append(sum(1 for ch in word if ch.isalpha()))
        else:
            lengths.append(len(word))
    return lengths


def task_func(text1, text2):
    lengths1 = _word_lengths(text1)
    lengths2 = _word_lengths(text2)
    nan = float('nan')
    if len(lengths1) != len(lengths2):
        return (nan, nan)
    n = len(lengths1)
    if n < 2:
        return (nan, nan)
    diffs = [a - b for a, b in zip(lengths1, lengths2)]
    mean = sum(diffs) / n
    var = sum((d - mean) ** 2 for d in diffs) / (n - 1)
    df = n - 1
    if var == 0:
        if mean == 0:
            return (nan, nan)
        return (math.copysign(math.inf, mean), 0.0)
    t_stat = mean / math.sqrt(var / n)
    x = df / (df + t_stat * t_stat)
    p_value = _betainc(df / 2.0, 0.5, x)
    p_value = min(max(p_value, 0.0), 1.0)
    return (t_stat, p_value)

