SENTENCES = ['This is a sentence', 'Another sentence here', 'More sentences']


def _strip_latin_diacritics(text):
    decomposed = unicodedata.normalize('NFD', text)
    result = []
    previous_is_latin = False
    for ch in decomposed:
        if unicodedata.combining(ch):
            if previous_is_latin:
                continue
            result.append(ch)
            continue
        previous_is_latin = ch.isalpha() and 'LATIN' in unicodedata.name(ch, '')
        result.append(ch)
    return unicodedata.normalize('NFC', ''.join(result))


def _tokenize(text):
    text = _strip_latin_diacritics(text).lower()
    return re.findall(r'(?u)\b\w\w+\b', text)


def task_func(s: str) -> np.ndarray:
    documents = [s] + SENTENCES
    tokenized = [_tokenize(doc) for doc in documents]
    vocabulary = sorted({token for tokens in tokenized for token in tokens})
    index = {word: i for i, word in enumerate(vocabulary)}
    vector = np.zeros(len(vocabulary), dtype=np.int64)
    for token in tokenized[0]:
        vector[index[token]] += 1
    return vector

