import math
import re


def task_func(text1, text2):
    def word_lengths(text):
        return [sum(char.isalpha() for char in word)
                for word in re.findall(r'\b\w+\b', text)]

    def beta_fraction(a, b, x):
        tiny = 1e-300
        c = 1.0
        d = 1.0 - (a + b) * x / (a + 1.0)
        if abs(d) < tiny:
            d = tiny
        d = 1.0 / d
        result = d
        for m in range(1, 1001):
            coefficients = (
                m * (b - m) * x / ((a + 2 * m - 1) * (a + 2 * m)),
                -(a + m) * (a + b + m) * x
                / ((a + 2 * m) * (a + 2 * m + 1)),
            )
            for coefficient in coefficients:
                d = 1.0 + coefficient * d
                c = 1.0 + coefficient / c
                if abs(d) < tiny:
                    d = tiny
                if abs(c) < tiny:
                    c = tiny
                d = 1.0 / d
                change = d * c
                result *= change
            if abs(change - 1.0) < 1e-14:
                break
        return result

    lengths1 = word_lengths(text1)
    lengths2 = word_lengths(text2)
    n = len(lengths1)
    if n != len(lengths2) or n < 2:
        return float('nan'), float('nan')

    differences = [a - b for a, b in zip(lengths1, lengths2)]
    mean = math.fsum(differences) / n
    variance = math.fsum((value - mean) ** 2 for value in differences) / (n - 1)
    if variance == 0.0:
        if mean == 0.0:
            return float('nan'), float('nan')
        return math.copysign(float('inf'), mean), 0.0

    statistic = mean / math.sqrt(variance / n)
    if statistic == 0.0:
        return statistic, 1.0

    degrees = n - 1
    x = degrees / (degrees + statistic * statistic)
    if x == 0.0:
        return statistic, 0.0
    if x == 1.0:
        return statistic, 1.0

    a = degrees / 2.0
    b = 0.5
    factor = math.exp(
        math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
        + a * math.log(x) + b * math.log1p(-x)
    )
    if x < (a + 1.0) / (a + b + 2.0):
        probability = factor * beta_fraction(a, b, x) / a
    else:
        probability = 1.0 - factor * beta_fraction(b, a, 1.0 - x) / b
    return statistic, min(1.0, max(0.0, probability))

