import math
import operator
import random


def task_func(data, n_clusters):
    n_clusters = operator.index(n_clusters)
    points = [tuple(float(value) for value in row) for row in data]
    if not points or not points[0]:
        raise ValueError('data must be a nonempty 2D numeric array')
    dimensions = len(points[0])
    if any(len(point) != dimensions for point in points):
        raise ValueError('all rows must have the same number of features')
    if any(not math.isfinite(value) for point in points for value in point):
        raise ValueError('data must contain only finite values')
    if not 1 <= n_clusters <= len(points):
        raise ValueError('n_clusters must be between 1 and the number of points')

    def distance_squared(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    rng = random.Random(42)
    best_inertia = math.inf
    best_labels = None

    for _ in range(10):
        centers = [points[rng.randrange(len(points))]]
        nearest = [distance_squared(point, centers[0]) for point in points]
        while len(centers) < n_clusters:
            total = sum(nearest)
            if total == 0:
                index = rng.randrange(len(points))
            else:
                threshold = rng.random() * total
                cumulative = 0.0
                index = len(points) - 1
                for i, weight in enumerate(nearest):
                    cumulative += weight
                    if cumulative > threshold:
                        index = i
                        break
            centers.append(points[index])
            nearest = [
                min(previous, distance_squared(point, centers[-1]))
                for point, previous in zip(points, nearest)
            ]

        for _ in range(300):
            groups = [[] for _ in range(n_clusters)]
            errors = []
            for i, point in enumerate(points):
                distances = [distance_squared(point, center) for center in centers]
                label = min(range(n_clusters), key=distances.__getitem__)
                groups[label].append(i)
                errors.append(distances[label])

            new_centers = []
            for label, indices in enumerate(groups):
                if indices:
                    new_centers.append(tuple(
                        sum(points[i][j] for i in indices) / len(indices)
                        for j in range(dimensions)
                    ))
                else:
                    index = max(range(len(points)), key=errors.__getitem__)
                    new_centers.append(points[index])
                    errors[index] = -1.0
            if new_centers == centers:
                break
            centers = new_centers

        labels = [
            min(range(n_clusters), key=lambda label: distance_squared(point, centers[label]))
            for point in points
        ]
        inertia = sum(
            distance_squared(point, centers[label])
            for point, label in zip(points, labels)
        )
        if best_labels is None or inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    result = {}
    for index, label in enumerate(best_labels):
        result.setdefault(label, []).append(index)
    return result

