    if any(len(point) != dimensions for point in points):
        raise ValueError('all rows must have the same length')
    if any(not math.isfinite(value) for point in points for value in point):
        raise ValueError('data must contain only finite values')
    if n_clusters > len(points):
        raise ValueError('n_clusters cannot exceed the number of samples')

    def squared_distance(left, right):
        return sum((a - b) ** 2 for a, b in zip(left, right))

    rng = random.Random(0)
    best_labels = None
    best_inertia = math.inf

    for _ in range(10):
        centers = [points[rng.randrange(len(points))]]
        distances = [squared_distance(point, centers[0]) for point in points]
        while len(centers) < n_clusters:
            total = sum(distances)
            if total == 0:
                centers.append(points[0])
                continue
            threshold = rng.random() * total
            cumulative = 0.0
            selected = len(points) - 1
            for index, distance in enumerate(distances):
                cumulative += distance
                if cumulative > threshold:
                    selected = index
                    break
            centers.append(points[selected])
            distances = [min(distance, squared_distance(point, centers[-1]))
                         for point, distance in zip(points, distances)]

        previous_labels = None
        for _ in range(300):
            labels = [min(range(n_clusters),
                          key=lambda label: squared_distance(point, centers[label]))
                      for point in points]
            if labels == previous_labels:
                break
            previous_labels = labels
            counts = [0] * n_clusters
            totals = [[0.0] * dimensions for _ in range(n_clusters)]
            for point, label in zip(points, labels):
                counts[label] += 1
                for dimension, value in enumerate(point):
                    totals[label][dimension] += value
            centers = [tuple(value / counts[label] for value in totals[label])
                       if counts[label] else centers[label]
                       for label in range(n_clusters)]

        labels = [min(range(n_clusters),
                      key=lambda label: squared_distance(point, centers[label]))
                  for point in points]
        inertia = sum(squared_distance(point, centers[label])
                      for point, label in zip(points, labels))
        if best_labels is None or inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    result = {label: array('q') for label in range(n_clusters)}
    for index, label in enumerate(best_labels):
        result[label].append(index)
    return result

