import re
import textwrap


def task_func(input_string, width):
    if width <= 0:
        raise ValueError('width must be greater than zero')

    wrapper = textwrap.TextWrapper(width=width)
    result = []

    for line in input_string.split('\n'):
        wrapped = []
        start = 0

        for match in re.finditer(r'\S+', line):
            word = match.group()
            if len(word) > width and '-' not in word:
                wrapped.extend(wrapper.wrap(line[start:match.start()]))
                wrapped.extend(
                    word[index:index + width]
                    for index in range(0, len(word), width)
                )
                start = match.end()

        wrapped.extend(wrapper.wrap(line[start:]))
        result.append('\n'.join(wrapped))

    return '\n'.join(result)

