import numpy as np


def task_func(word: str) -> tuple[np.ndarray, float]:
    differences = np.diff([ord(letter) for letter in word])
    if differences.size == 0:
        return differences, 0.0

    total = int(differences.sum())
    if total == 0:
        entropy = math.nan if np.any(differences == 0) else -math.inf
        return differences, entropy

    probabilities = [int(value) / total for value in differences]
    if any(probability < 0 for probability in probabilities):
        return differences, -math.inf

    entropy = -sum(p * math.log(p) for p in probabilities if p > 0)
    return differences, float(entropy)

