def task_func(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        raise ValueError("The DataFrame is empty.")
    for column in df.columns:
        if not pd.api.types.is_numeric_dtype(df[column]):
            raise TypeError("The DataFrame contains non-numeric data types.")
    if df.isnull().values.any():
        raise ValueError("The DataFrame contains NaN values.")

    cumulative = df.astype(float).cumsum()
    result = {}
    for column in cumulative.columns:
        values = cumulative[column]
        col_min = values.min()
        col_max = values.max()
        span = col_max - col_min
        if span == 0:
            result[column] = values * 0.0
        else:
            result[column] = (values - col_min) / span

    output = pd.DataFrame(result, columns=df.columns)
    return output.reset_index(drop=True)

