}


def task_func(area_string, data=DATA):
    areas = [float(value.replace(",", "")) for value in data["Area_String"]]
    prices = [float(value) for value in data["Price"]]
    if not areas or len(areas) != len(prices):
        raise ValueError("Area and price data must have equal, nonzero lengths.")
    denominator = math.fsum(area * area for area in areas)
    numerator = math.fsum(area * price for area, price in zip(areas, prices))
    coefficient = numerator / denominator if denominator else 0.0
    return float(coefficient * float(area_string.replace(",", "")))

