        }
    areas = [float(str(a).replace(",", "")) for a in data["Area_String"]]
    prices = [float(p) for p in data["Price"]]
    sum_xy = sum(x * y for x, y in zip(areas, prices))
    sum_xx = sum(x * x for x in areas)
