    prices = [float(value) for value in data["Price"]]
    if not areas or len(areas) != len(prices):
        raise ValueError("Training areas and prices must have equal, nonzero lengths.")

    mean_area = fsum(areas) / len(areas)
    mean_price = fsum(prices) / len(prices)
    variance = fsum((area - mean_area) ** 2 for area in areas)
    covariance = fsum(
        (area - mean_area) * (price - mean_price)
        for area, price in zip(areas, prices)
    )
    slope = covariance / variance if variance else 0.0
    intercept = mean_price - slope * mean_area
    return float(intercept + slope * float(area_string.replace(",", "")))

