import math


def task_func(data):
    scores = [float(s) for s in data.get('Score_String', [])]
    grades = [str(g) for g in data.get('Grade', [])]

    if len(scores) < 2 or len(grades) < 2:
        return float('nan')

    has_upper = any(ch.isupper() for g in grades for ch in g)
    has_lower = any(ch.islower() for g in grades for ch in g)
    if has_upper and has_lower:
        grades = [g.upper() for g in grades]

    categories = sorted(set(grades))
    mapping = {label: index for index, label in enumerate(categories)}
    encoded = [float(mapping[g]) for g in grades]

    n = len(scores)
    mean_x = sum(scores) / n
    mean_y = sum(encoded) / n
    dx = [x - mean_x for x in scores]
    dy = [y - mean_y for y in encoded]
    sxy = sum(a * b for a, b in zip(dx, dy))
    sxx = sum(a * a for a in dx)
    syy = sum(b * b for b in dy)

    denominator = math.sqrt(sxx * syy)
    if denominator == 0:
        return float('nan')

    r = sxy / denominator
    return max(-1.0, min(1.0, r))

import math


def task_func(data):
    scores = [float(value) for value in data['Score_String']]
    grades = [grade.upper() for grade in data['Grade']]
    if len(scores) != len(grades):
        raise ValueError('Scores and grades must have the same length.')
    if len(scores) < 2 or any(not math.isfinite(score) for score in scores):
        return float('nan')

    codes = {grade: index for index, grade in enumerate(sorted(set(grades)))}
    encoded = [codes[grade] for grade in grades]
    scale = max(abs(score) for score in scores)
    if scale == 0 or len(codes) == 1:
        return float('nan')

    scaled_scores = [score / scale for score in scores]
    count = len(scores)
    score_mean = math.fsum(scaled_scores) / count
    grade_mean = math.fsum(encoded) / count
    score_deviations = [score - score_mean for score in scaled_scores]
    grade_deviations = [grade - grade_mean for grade in encoded]
    score_norm = math.hypot(*score_deviations)
    grade_norm = math.hypot(*grade_deviations)
    if score_norm == 0 or grade_norm == 0:
        return float('nan')

    correlation = math.fsum(
        (score / score_norm) * (grade / grade_norm)
        for score, grade in zip(score_deviations, grade_deviations)
    )
    return max(-1.0, min(1.0, correlation))

