import re


def task_func(result):
    counts = Counter()
    last_seen = {}
    position = 0

    for entry in result:
        for key, value in entry.items():
            if isinstance(key, str) and re.match(r"^https?://", key):
                counts[value] += 1
                last_seen[value] = position
                position += 1

    if not counts:
        return {}

    winner = max(counts, key=lambda value: (counts[value], last_seen[value]))
    return {winner: counts[winner]}

