from collections import Counter


def _tokenize(text):
    tokens = []
    for match in re.finditer(r"\w+(?:-\w+)*", text.lower()):
        token = match.group(0)
        if "-" in token:
            parts = token.split("-")
            if all(part.isalpha() and len(part) >= 2 for part in parts):
                tokens.extend(parts)
            else:
                tokens.append(token)
        elif len(token) >= 2:
            tokens.append(token)
    return tokens


def task_func(texts):
    if not texts or all(not text.strip() for text in texts):
        return [], []

    cleaned = [re.sub(r"http[s]?://\S+", "", text) for text in texts]
    counts = [Counter(_tokenize(text)) for text in cleaned]

    vocabulary = sorted(set().union(*counts))
    if not vocabulary:
        return [], []

    n_docs = len(counts)
    doc_freq = Counter()
    for count in counts:
        doc_freq.update(count.keys())

    idf = {
        word: math.log((1 + n_docs) / (1 + doc_freq[word])) + 1.0
        for word in vocabulary
    }

    rows = []
    for count in counts:
        values = [count.get(word, 0) * idf[word] for word in vocabulary]
        norm = math.sqrt(sum(v * v for v in values))
        if norm > 0:
            values = [v / norm for v in values]
        rows.append(tuple(round(v, 8) for v in values))

    return rows, vocabulary

